// VentureSchool sector map and startup metrics guide.
// Benchmarks are rough guides for early-stage companies. They move with markets and vary by business model.
window.VS_METRICS = {
  // Revenue and growth
  arr: { name: 'Annual recurring revenue (ARR)', what: 'The yearly value of subscription contracts active today.', how: 'Monthly recurring revenue times 12. Exclude one-time fees, services, and unsigned contracts.', good: 'Size depends on stage. Growth and retention matter more than the number itself.' },
  arr_growth: { name: 'Revenue growth rate', what: 'How fast recurring revenue is growing.', how: 'Revenue now divided by revenue a year (or month) ago, minus 1.', good: 'Early software companies that raise easily often grow 2 to 3 times a year. At seed, 10 to 20% month over month gets attention.' },
  usage_growth: { name: 'Usage growth', what: 'Growth in the billed unit for usage-priced products: API calls, compute, transactions, or seats.', how: 'Billed units this period divided by the same period last year, minus 1.', good: 'Should grow faster than customer count, showing customers use more over time.' },
  bookings_backlog: { name: 'Bookings and backlog', what: 'Signed orders and contracts not yet delivered or recognized as revenue.', how: 'Total value of signed, undelivered orders.', good: 'Growing backlog with a short gap to delivery. Check how firm the orders are.' },

  // Retention
  nrr: { name: 'Net revenue retention (NRR)', what: 'Whether existing customers spend more or less over time.', how: 'Revenue now from customers who were active a year ago, divided by their revenue a year ago. Includes expansion, downgrades, and churn.', good: 'Above 110% is good, above 120% is strong for business software. Small-business products run lower.' },
  grr: { name: 'Gross revenue retention (GRR)', what: 'How much revenue you keep, ignoring expansion.', how: 'Same as NRR but counting only churn and downgrades. Cannot exceed 100%.', good: 'Above 90% for mid-market and enterprise. Above 80% for small-business products.' },
  logo_churn: { name: 'Customer churn', what: 'The share of customers who leave in a period.', how: 'Customers lost in the period divided by customers at the start.', good: 'Under about 2% a month for small-business software. Under 10% a year for enterprise.' },
  cohort_retention: { name: 'Cohort retention', what: 'The share of a group of users who started together that is still active over time.', how: 'Active users from the cohort at day or month N, divided by the cohort size.', good: 'The curve should flatten instead of sliding toward zero. Compare with similar products, not other categories.' },
  subscriber_churn: { name: 'Subscriber churn', what: 'The share of paying consumer subscribers who cancel each month.', how: 'Cancellations in the month divided by subscribers at the start.', good: 'Varies widely. Under 5% a month is strong for many consumer subscriptions.' },
  policy_retention: { name: 'Policy retention', what: 'The share of insurance policies renewed at the end of their term.', how: 'Policies renewed divided by policies up for renewal.', good: 'Compare with the same line of insurance. High retention lowers acquisition cost per year of premium.' },
  buyer_repeat: { name: 'Buyer repeat rate', what: 'How often buyers come back to transact again.', how: 'Share of buyers from a cohort who transact again within a set period, or GMV from a cohort over time.', good: 'Cohort GMV that holds or grows over time is a strong marketplace signal.' },
  repeat_rate: { name: 'Repeat purchase rate', what: 'The share of customers who buy again.', how: 'Customers with two or more orders in 12 months divided by all customers in that cohort.', good: 'Depends on purchase frequency. Higher repeat lets you spend more to acquire customers.' },

  // Efficiency and unit economics
  gross_margin: { name: 'Gross margin', what: 'How much of each dollar of revenue is left after the direct cost of delivering the product.', how: '(Revenue minus cost of goods sold) divided by revenue. For software, include hosting, model costs, and support.', good: 'Software: 75 to 85%. AI products often start at 40 to 60% and should improve. Hardware: often 25 to 50%.' },
  cost_per_task: { name: 'Cost to serve per task', what: 'What it costs to deliver one unit of work in an AI product.', how: 'Model, compute, and human review costs divided by tasks completed.', good: 'Should fall steadily as models get cheaper and the company routes work to smaller models.' },
  cac: { name: 'Customer acquisition cost (CAC)', what: 'What it costs to win one new customer.', how: 'Sales and marketing spend in a period divided by new customers won in that period.', good: 'Only meaningful next to what a customer is worth. See payback and LTV to CAC.' },
  cac_payback: { name: 'CAC payback', what: 'How many months of gross profit it takes to earn back the cost of acquiring a customer.', how: 'CAC divided by (monthly revenue per customer times gross margin).', good: 'Under 12 months is excellent. 12 to 18 is healthy for many business software companies.' },
  ltv_cac: { name: 'LTV to CAC', what: 'Lifetime gross profit of a customer compared with what it cost to win them.', how: '(Average revenue per customer times gross margin times expected lifetime) divided by CAC.', good: '3 or more is the usual target. Be skeptical when lifetime is estimated from little history.' },
  burn_multiple: { name: 'Burn multiple', what: 'How much cash is burned to add each dollar of new recurring revenue.', how: 'Net cash burned in a period divided by net new ARR in that period.', good: 'Under 1x excellent, 1 to 1.5x good, above 3x a warning. Most useful from Series A on.' },
  magic_number: { name: 'Sales efficiency (magic number)', what: 'How much new revenue each dollar of sales and marketing produces.', how: 'Increase in quarterly recurring revenue times 4, divided by the previous quarter\'s sales and marketing spend.', good: 'Above about 0.75 suggests efficient spend. Below 0.5 suggests a problem in the sales motion.' },
  rule_of_40: { name: 'Rule of 40', what: 'A balance check between growth and profitability for later-stage software.', how: 'Revenue growth rate plus profit margin (often free cash flow margin), in percent.', good: '40 or more.' },
  contribution_margin: { name: 'Contribution margin per order', what: 'Profit on each order after all variable costs.', how: 'Order revenue minus product cost, shipping, payment fees, returns, and variable marketing.', good: 'Must be positive and rising with repeat orders. Many consumer brands fail here.' },
  runway: { name: 'Runway', what: 'How many months the company can operate before running out of cash.', how: 'Cash in the bank divided by monthly net burn.', good: 'Raise with 6 or more months left. Aim for 18 to 24 months after a raise.' },
  milestone_runway: { name: 'Runway to the next value milestone', what: 'Whether cash lasts until the next result that raises the company\'s value, such as clinical data or a pilot.', how: 'Months of cash compared with months to the milestone.', good: 'Cash should last well past the milestone, with room for delays.' },

  // Sales motion
  acv: { name: 'Average contract value (ACV)', what: 'The yearly value of a typical customer contract.', how: 'Total annual contract value divided by number of contracts.', good: 'No target on its own. It sets the sales motion: low ACV needs self-serve, high ACV supports a sales team.' },
  sales_cycle: { name: 'Sales cycle length', what: 'How long it takes to close a deal.', how: 'Average days from first meaningful contact to signed contract.', good: 'Should match ACV. Long cycles are fine for large contracts but slow growth and burn cash.' },
  pipeline_coverage: { name: 'Pipeline coverage', what: 'Whether there are enough qualified deals to hit the sales target.', how: 'Value of qualified pipeline divided by the revenue target for the period.', good: 'About 3x is a common target.' },
  pilot_conversion: { name: 'Pilot-to-paid conversion', what: 'How many trials or pilots become paying contracts.', how: 'Paid contracts divided by pilots completed.', good: 'High conversion with short pilots is a strong sign. Many pilots that never convert is a warning.' },
  free_to_paid: { name: 'Free-to-paid conversion', what: 'The share of free users or teams that start paying.', how: 'New paying accounts divided by new free accounts in the same cohort.', good: 'Low single digits is common for product-led software. Track it by cohort.' },
  seat_expansion: { name: 'Seat expansion', what: 'Growth in paid seats inside existing customers.', how: 'Seats now divided by seats at purchase, for each customer cohort.', good: 'Steady expansion without sales effort is a strong product-market fit signal.' },
  dev_adoption: { name: 'Developer adoption', what: 'How many developers use a developer tool or open source project.', how: 'Weekly active developers, package downloads, or active installs.', good: 'A leading indicator. Look for growth driven by usage, and for companies with many developers using it.' },
  pepm: { name: 'Revenue per employee per month (PEPM)', what: 'Pricing unit for HR and benefits products.', how: 'Monthly revenue divided by employees covered on the platform.', good: 'Depends on the product. Watch whether it rises as you add modules.' },

  // Consumer
  dau_mau: { name: 'DAU to MAU', what: 'How often monthly users come back each day.', how: 'Average daily active users divided by monthly active users.', good: 'Around 20% is decent for many apps. Above 50% is exceptional and typical only of messaging and social products.' },
  activation: { name: 'Activation rate', what: 'The share of new sign-ups who reach the first meaningful action.', how: 'Users completing the key action within a set time, divided by new sign-ups.', good: 'Define the key action carefully. Improvements here lift every later metric.' },
  arpu: { name: 'Average revenue per user (ARPU)', what: 'Revenue earned per user.', how: 'Revenue in a period divided by average active users in that period.', good: 'Compare with acquisition cost and retention.' },
  paid_conversion: { name: 'Paid conversion', what: 'The share of users who pay.', how: 'Paying users divided by active users.', good: 'Varies by model. Freemium consumer apps often convert a few percent.' },
  organic_share: { name: 'Organic share of new users', what: 'How much growth comes without paid marketing.', how: 'New users from organic, referral, and word of mouth divided by all new users.', good: 'Higher is better. Growth that depends on paid ads often stops when spending stops.' },
  engagement_time: { name: 'Time spent', what: 'How much attention the product holds.', how: 'Minutes per active user per day.', good: 'Compare with direct alternatives. More is not always better for utility products.' },
  arpdau: { name: 'Revenue per daily active user (ARPDAU)', what: 'Monetization in games and ad-supported apps.', how: 'Daily revenue divided by daily active users.', good: 'Compare within the same genre.' },
  payer_rate: { name: 'Payer conversion', what: 'The share of players who make any purchase.', how: 'Paying players divided by active players in a period.', good: 'Often low single digits in free-to-play games. Revenue concentrates in a small group of payers.' },
  creator_count: { name: 'Active creators', what: 'The supply side of creator and social platforms.', how: 'Creators who publish at least once in a period.', good: 'Look at retention of creators and how many earn meaningful income.' },

  // Commerce and marketplaces
  gmv: { name: 'Gross merchandise value (GMV)', what: 'The total value of transactions on the platform.', how: 'Sum of all transaction values in a period, before the platform\'s cut.', good: 'Not revenue. Always pair with take rate.' },
  take_rate: { name: 'Take rate', what: 'The share of each transaction the platform keeps as revenue.', how: 'Net revenue divided by GMV.', good: 'Ranges from a few percent to over 20% depending on the value the platform adds. Rising take rate without losing volume is strong.' },
  liquidity: { name: 'Liquidity (match or fill rate)', what: 'Whether buyers and sellers actually find each other.', how: 'Share of listings that sell, or share of requests that get filled, in a set time.', good: 'High and rising in each local market. The core marketplace health metric.' },
  time_to_match: { name: 'Time to match', what: 'How fast a request is filled.', how: 'Median time from request to accepted match.', good: 'Falling over time as density grows.' },
  supply_utilization: { name: 'Supply utilization', what: 'How much of the available supply gets used.', how: 'Hours booked divided by hours available, or units sold divided by units listed.', good: 'High utilization keeps suppliers on the platform.' },
  aov: { name: 'Average order value (AOV)', what: 'The typical size of an order.', how: 'Revenue divided by number of orders.', good: 'Higher AOV makes shipping and acquisition costs easier to cover.' },
  return_rate: { name: 'Return rate', what: 'The share of orders returned.', how: 'Returned orders divided by total orders.', good: 'Varies by category. Apparel runs much higher than most others.' },
  inventory_turns: { name: 'Inventory turnover', what: 'How fast inventory sells.', how: 'Cost of goods sold divided by average inventory.', good: 'Higher means less cash tied up in stock.' },

  // Fintech and insurance
  tpv: { name: 'Total payment volume (TPV)', what: 'The total value of payments processed.', how: 'Sum of payment value in a period.', good: 'Not revenue. Pair with net take rate.' },
  net_take_rate: { name: 'Net take rate', what: 'What the company keeps from each dollar processed after network and partner costs.', how: 'Net revenue divided by payment volume.', good: 'Often a fraction of a percent to a few percent. Watch for pressure as volume grows.' },
  loss_rate: { name: 'Fraud and loss rate', what: 'Losses from fraud, chargebacks, and errors.', how: 'Losses divided by volume, usually in basis points.', good: 'Low and stable. A sudden rise can erase margins.' },
  default_rate: { name: 'Default or charge-off rate', what: 'The share of loans that are not repaid.', how: 'Loan balances written off divided by average loan balances, by vintage.', good: 'Compare with the pricing assumptions. Look at each origination cohort, not the blended number.' },
  nim: { name: 'Net interest margin', what: 'What a lender earns on its loans after its own cost of funds.', how: '(Interest income minus interest paid on funding) divided by average loan balance.', good: 'Must cover losses and operating costs with room to spare.' },
  cost_of_capital: { name: 'Cost of capital', what: 'What the company pays for the money it lends.', how: 'Weighted interest rate on credit lines, deposits, or loan sales.', good: 'Falling cost of capital as the company proves its loans perform is a key milestone.' },
  originations: { name: 'Loan originations', what: 'New loans issued.', how: 'Value of new loans in a period.', good: 'Growth only counts if loss rates stay in line with pricing.' },
  deposits: { name: 'Deposits and funded accounts', what: 'How much money customers keep with the company.', how: 'Total deposits; share of accounts with a balance.', good: 'Funded and active accounts matter far more than sign-ups.' },
  primary_account: { name: 'Primary account share', what: 'Whether customers use you as their main financial account.', how: 'Share of customers with direct deposit or main spending through the product.', good: 'Higher primary use means higher revenue per customer and lower churn.' },
  aum: { name: 'Assets under management (AUM)', what: 'Customer money invested or held on the platform.', how: 'Total value of customer assets.', good: 'Revenue usually scales with AUM, so growth from new money (not market gains) matters.' },
  revenue_per_account: { name: 'Revenue per account', what: 'How much each customer account earns.', how: 'Revenue divided by active accounts.', good: 'Compare with acquisition cost and cost to serve.' },
  cost_to_serve: { name: 'Cost to serve per account', what: 'The ongoing cost of supporting each customer.', how: 'Support, compliance, and processing costs divided by active accounts.', good: 'Should fall with scale and automation.' },
  gwp: { name: 'Gross written premium', what: 'Total insurance premiums sold.', how: 'Sum of premiums on policies written in a period.', good: 'Growth only counts if loss ratio holds.' },
  loss_ratio: { name: 'Loss ratio', what: 'How much of premium is paid out in claims.', how: 'Claims incurred divided by premiums earned.', good: 'Compare with the same line of insurance. Rising loss ratio is the main risk in insurtech.' },
  combined_ratio: { name: 'Combined ratio', what: 'Whether insurance underwriting is profitable.', how: '(Claims plus operating expenses) divided by premiums earned.', good: 'Below 100% means underwriting profit.' },
  attach_rate: { name: 'Attach rate', what: 'For embedded products, how often a partner\'s customers add yours.', how: 'Transactions with your product attached divided by eligible partner transactions.', good: 'Rising attach rate shows the offer fits the moment of purchase.' },

  // Healthcare and life sciences
  pmpm: { name: 'Revenue per member per month (PMPM)', what: 'The pricing unit for many health programs paid by employers or health plans.', how: 'Monthly revenue divided by enrolled members.', good: 'Must be justified by savings or outcomes the payer can measure.' },
  clinical_outcomes: { name: 'Clinical outcomes', what: 'Measured improvement in patient health.', how: 'Change in a clinical measure, such as blood sugar or readmissions, compared with a control group.', good: 'Credible, published, or independently verified outcomes are what payers buy.' },
  engagement_rate: { name: 'Patient engagement', what: 'The share of enrolled patients actively using the program.', how: 'Active patients divided by enrolled patients over a period.', good: 'Low engagement usually means weak outcomes, whatever the enrollment numbers say.' },
  reimbursement: { name: 'Reimbursement coverage', what: 'Whether insurers pay for the service.', how: 'Share of revenue paid by insurers; billing codes and payer contracts in place.', good: 'Clear, existing billing codes and contracted payers reduce risk a lot.' },
  payer_contracts: { name: 'Payer and employer contracts', what: 'Signed agreements with the organizations that pay.', how: 'Number and size of contracts; covered lives.', good: 'Contracts with large payers are slow to win and very valuable.' },
  provider_utilization: { name: 'Clinician utilization', what: 'How much clinician time is used for paid care.', how: 'Booked clinical hours divided by available hours.', good: 'High utilization keeps care delivery margins healthy.' },
  regulatory_path: { name: 'Regulatory pathway and status', what: 'The approvals a product needs before it can be sold, and progress toward them.', how: 'The pathway (for US devices, for example 510(k), De Novo, or PMA) and current stage.', good: 'A clear pathway with a realistic timeline and budget.' },
  clinical_stage: { name: 'Clinical stage', what: 'Where a therapy is in development.', how: 'Preclinical, Phase 1, Phase 2, Phase 3, or approved.', good: 'Each successful stage raises the odds of approval and the company\'s value. Know the typical success rates for the disease area.' },
  asp_unit_margin: { name: 'Selling price and unit margin', what: 'What each unit sells for and what it costs to make.', how: 'Average selling price; (price minus unit cost) divided by price.', good: 'Unit margin should improve with volume. Many hardware companies need a clear path to 40% or more.' },
  installed_base: { name: 'Installed base and utilization', what: 'How many devices or systems are deployed and how much they are used.', how: 'Units in the field; average uses per unit per week.', good: 'High utilization drives recurring revenue from consumables, software, or service.' },

  // Hardware, climate, industrial
  lois_to_orders: { name: 'Letters of intent to orders', what: 'Whether early interest turns into commitments.', how: 'Signed purchase orders divided by letters of intent.', good: 'LOIs are cheap to sign. Conversion to paid orders is the real signal.' },
  yield: { name: 'Manufacturing yield', what: 'The share of units produced that pass quality checks.', how: 'Good units divided by units started.', good: 'Rising toward target as production scales. Low yield destroys unit margins.' },
  capacity_deployed: { name: 'Capacity deployed', what: 'Energy capacity installed and operating.', how: 'Megawatts or megawatt-hours deployed.', good: 'Growth in operating capacity, not just announced projects.' },
  lcoe: { name: 'Levelized cost of energy or storage', what: 'The lifetime cost per unit of energy produced or stored.', how: 'Total lifetime costs divided by lifetime energy delivered.', good: 'Must beat the alternative the customer would otherwise use, without relying on subsidies that may change.' },
  capacity_factor: { name: 'Asset utilization', what: 'How much of the time an asset is producing or working.', how: 'Actual output divided by maximum possible output over a period.', good: 'Compare with similar assets. Utilization drives returns on capital-heavy businesses.' },
  offtake: { name: 'Offtake contracts', what: 'Long-term agreements to buy the product, often needed to finance projects.', how: 'Volume and value under signed offtake agreements.', good: 'Signed, bankable offtakes with credible buyers unlock project financing.' },
  project_pipeline: { name: 'Project pipeline', what: 'Projects in development, by stage.', how: 'Number and capacity of projects at each stage, from early development to operating.', good: 'Look at conversion between stages, not just the total.' },
  cost_per_ton: { name: 'Cost per ton', what: 'What it costs to remove or avoid one ton of carbon dioxide.', how: 'Total cost divided by tons removed or avoided.', good: 'Must fall over time toward what buyers will pay at scale.' },
  verified_tons: { name: 'Verified tons delivered', what: 'Carbon removal or avoidance actually delivered and checked by a third party.', how: 'Tons verified under a recognized standard.', good: 'Delivered and verified tons matter far more than tons pre-sold.' },
  cost_per_mile: { name: 'Cost per mile or per trip', what: 'The operating cost of moving people or goods.', how: 'Operating costs divided by miles or trips.', good: 'Falling with density, automation, or better routing.' },
  on_time: { name: 'On-time rate', what: 'Reliability of deliveries or service.', how: 'Deliveries on time divided by all deliveries.', good: 'High and stable. Shippers switch quickly after failures.' },
  margin_per_load: { name: 'Gross margin per shipment', what: 'Profit on each load or shipment.', how: 'Price charged minus carrier or direct delivery cost, per shipment.', good: 'Stable or rising as volume grows.' },
  shipment_volume: { name: 'Shipment volume', what: 'How much freight or how many orders move through the platform.', how: 'Loads, shipments, or orders per week.', good: 'Steady growth with repeat shippers.' },
  program_stage: { name: 'Contract stage', what: 'How far a defense or government product has moved toward large, recurring contracts.', how: 'Pilot, small innovation contracts, production contracts, or long-term program funding.', good: 'Moving from pilots to production contracts is the key milestone.' },

  // Education, work, real estate, agriculture, government
  enrollment: { name: 'Enrollment', what: 'Learners signed up or enrolled.', how: 'New enrollments per period.', good: 'Only meaningful with completion and outcomes.' },
  completion_rate: { name: 'Completion rate', what: 'The share of learners who finish.', how: 'Learners completing divided by learners enrolled.', good: 'Self-paced online courses often see low completion. Higher completion signals real value.' },
  outcome_rate: { name: 'Learner outcomes', what: 'Results learners achieve, such as job placement or test scores.', how: 'Share of completers who reach the stated outcome within a set time.', good: 'Verified outcomes justify higher prices and employer or district funding.' },
  units_managed: { name: 'Units or properties managed', what: 'The footprint of property software or services.', how: 'Number of units or properties on the platform.', good: 'Growth with low churn among property managers.' },
  transaction_volume: { name: 'Transaction volume', what: 'Value or number of property transactions completed.', how: 'Deals closed and their total value per period.', good: 'Sensitive to interest rates and housing cycles. Look at share of market, not just volume.' },
  acres_managed: { name: 'Acres under management', what: 'The farmland using the product.', how: 'Total acres enrolled.', good: 'Renewal after a full growing season is the real test.' },
  customer_roi: { name: 'Customer return on investment', what: 'The measurable gain customers get, such as yield increase or cost saved.', how: 'Value gained divided by what the customer pays.', good: 'A clear, measured ROI of several times the price sells itself.' },
  units_fielded: { name: 'Systems fielded', what: 'How many units are in the hands of real operators, not just in tests or demos.', how: 'Count of systems delivered and in active use, and how many units each customer has ordered again.', good: 'Repeat orders from the same unit or command show the product works in the field.' },
  dual_use_share: { name: 'Commercial revenue share', what: 'How much revenue comes from commercial customers rather than government.', how: 'Commercial revenue divided by total revenue.', good: 'A real commercial business smooths out slow, lumpy government budgets. Not required, but it lowers risk.' },
  deployment_time: { name: 'Time to deploy', what: 'How long it takes from a signed contract to the product working for the customer.', how: 'Days or months from signature to first real use, averaged across recent customers.', good: 'Shorter is better. Long, custom deployments usually mean services revenue disguised as product.' },
  cost_parity: { name: 'Cost versus the incumbent', what: 'Whether the product is cheaper, or can become cheaper, than what customers use today.', how: 'Your cost per unit (per kilogram, per ton, per kilowatt hour, per system) compared with the current option, today and at planned scale.', good: 'A credible path to equal or lower cost without subsidies. Many hard tech companies fail on this alone.' },
  cost_per_kg: { name: 'Cost per kilogram to orbit', what: 'What it costs a customer to put mass in orbit with your vehicle.', how: 'Price of a launch divided by the payload mass it can carry to the target orbit.', good: 'Falling cost per kilogram and a steady launch cadence. Missed launch dates are the common failure.' },
  flight_heritage: { name: 'Flight heritage', what: 'The record of hardware that has worked in space or in flight.', how: 'Missions flown, successful missions, and hours or months of operation in orbit.', good: 'Customers, especially government, often require proven hardware. The first successful mission changes everything.' },
  technical_milestones: { name: 'Technical milestones', what: 'Progress on the hard technical numbers that decide whether the product can work at all.', how: 'For quantum, for example, error rates and the number of usable logical qubits; for fusion, energy gain; for chips, performance per watt.', good: 'Hitting published milestones on schedule. Compare against the company\'s own roadmap and against competitors.' },
  compute_utilization: { name: 'Compute utilization', what: 'How much of the available compute capacity is sold and in use.', how: 'Hours of GPUs or servers billed divided by hours available.', good: 'High and stable utilization, with long contracts, covers the cost of expensive hardware.' },
  compute_cost_share: { name: 'Compute cost as a share of revenue', what: 'How much of every dollar of revenue goes to training and running models.', how: 'Compute spending divided by revenue, split into training and serving.', good: 'Should fall over time as models get cheaper to run and prices hold.' },
  eval_performance: { name: 'Model quality on evaluations', what: 'How well a model performs on the tasks customers care about, compared with alternatives.', how: 'Scores on public benchmarks and, more importantly, on customers\' own task sets, against cost.', good: 'Leading on the tasks that matter at a lower cost. Public benchmark scores alone can be gamed.' },
  false_positive_rate: { name: 'False positive rate', what: 'How often a security product raises an alert that turns out to be nothing.', how: 'False alerts divided by all alerts, from customer data.', good: 'Lower is better. Teams switch off noisy tools, which kills retention.' },
  pipeline_programs: { name: 'Drug pipeline', what: 'The drug programs the company is developing and how far each has gone.', how: 'Number of programs by stage: discovery, preclinical, and each clinical phase.', good: 'At least one program moving into the clinic shows the platform produces real drugs, not just predictions.' },
  partnership_value: { name: 'Pharma partnership value', what: 'Deals with drug companies that pay for access to the platform or programs.', how: 'Upfront cash, near-term milestones, and royalties. Separate cash received from the headline value.', good: 'Upfront cash and repeat partners. Headline deal values are mostly milestones that may never be paid.' },
  pull_through: { name: 'Consumables pull-through', what: 'Recurring revenue from supplies used by each installed instrument.', how: 'Consumables revenue divided by the number of instruments installed, per year.', good: 'Rising pull-through per instrument means customers use the product more and revenue becomes recurring.' },
  permitting_stage: { name: 'Permitting status', what: 'Progress on the licenses and permits needed to build and operate.', how: 'Each required permit or license, its stage, and expected date.', good: 'Permits in hand or on a clear timeline. Permitting delays can take years and sink projects.' },
  driverless_miles: { name: 'Driverless miles and interventions', what: 'How far vehicles drive without a human, and how often humans have to step in.', how: 'Miles driven with no safety driver, and miles per intervention, by city and conditions.', good: 'Steady improvement in miles per intervention, in more places and conditions.' },
  model_usage_mix: { name: 'Revenue mix by customer type', what: 'Where an AI company\'s revenue comes from: consumers, developers through an API, or enterprise contracts.', how: 'Revenue by segment as a share of the total, and growth of each.', good: 'Enterprise contracts tend to be stickier. API revenue can move quickly to a cheaper model.' },
  contract_value: { name: 'Contract value and renewals', what: 'Size and stickiness of public sector contracts.', how: 'Annual contract value; share of contracts renewed.', good: 'Public sector contracts are slow to win and tend to renew once in place.' }
};

window.VS_SECTORS = [
  { id: 'ai', name: 'Artificial intelligence', about: 'Companies building AI models, the infrastructure to run them, and products built on them.',
    subsectors: [
      { id: 'foundation-models', name: 'Foundation models', about: 'Companies that train large general models for language, images, video, code, or science, and sell access to them.', metrics: ['arr_growth', 'model_usage_mix', 'compute_cost_share', 'eval_performance', 'gross_margin', 'nrr'], watch: 'Training costs are enormous and the leaders spend the most. A smaller lab needs a clear niche, a cost advantage, or data no one else has.' },
      { id: 'ai-infra', name: 'AI infrastructure', about: 'Model hosting, inference, evaluation, data, and tooling for teams building with AI.', metrics: ['usage_growth', 'gross_margin', 'cost_per_task', 'nrr', 'logo_churn', 'acv'], watch: 'Large cloud and model providers can bundle similar features. Look for something they will not build.' },
      { id: 'ai-compute', name: 'AI chips and compute', about: 'New chips built for AI, and clouds that rent out GPU capacity.', metrics: ['compute_utilization', 'bookings_backlog', 'technical_milestones', 'gross_margin', 'cost_of_capital'], watch: 'Hardware is expensive and goes out of date quickly. Long contracts with strong customers protect against falling prices.' },
      { id: 'ai-apps', name: 'AI applications and agents', about: 'Products that use AI models to do work for a specific job, such as legal drafting or support.', metrics: ['arr_growth', 'gross_margin', 'cost_per_task', 'grr', 'pilot_conversion', 'nrr'], watch: 'Easy to build a demo, hard to hold customers. Retention after competitors appear is the key signal.' }
    ] },
  { id: 'software', name: 'Enterprise software', about: 'Software sold to businesses, usually by subscription.',
    subsectors: [
      { id: 'horizontal-saas', name: 'Horizontal SaaS', about: 'Tools any kind of company can use, such as collaboration, CRM, or finance software.', metrics: ['arr', 'arr_growth', 'nrr', 'grr', 'gross_margin', 'cac_payback', 'burn_multiple', 'magic_number'], watch: 'Crowded categories. Look for a sharp wedge and strong net revenue retention.' },
      { id: 'vertical-saas', name: 'Vertical SaaS', about: 'Software built for one industry, such as clinics, contractors, or restaurants.', metrics: ['arr', 'arr_growth', 'logo_churn', 'nrr', 'acv', 'cac_payback', 'gross_margin'], watch: 'Market size is capped by the industry. Payments and add-on products often expand revenue per customer.' },
      { id: 'devtools', name: 'Developer tools', about: 'Products used by software engineers to build, test, and run code.', metrics: ['dev_adoption', 'free_to_paid', 'seat_expansion', 'nrr', 'arr_growth', 'gross_margin'], watch: 'Bottom-up adoption comes first. The question is whether it turns into company-wide contracts.' },
      { id: 'data-analytics', name: 'Data and analytics', about: 'Databases, pipelines, and tools for analyzing data.', metrics: ['usage_growth', 'nrr', 'gross_margin', 'acv', 'sales_cycle', 'arr_growth'], watch: 'Usage-based revenue can swing with customers\' budgets. Watch cohort usage over time.' },
      { id: 'legal-pro', name: 'Legal and professional services software', about: 'Software for law firms, accountants, consultants, and in-house legal teams.', metrics: ['arr', 'acv', 'seat_expansion', 'nrr', 'pilot_conversion', 'gross_margin'], watch: 'Firms bill by the hour, so tools that save time can cut their revenue. Pricing by outcome or seat matters.' }
    ] },
  { id: 'cyber', name: 'Cybersecurity', about: 'Products that protect companies, governments, and infrastructure from attacks and help them meet security rules.',
    subsectors: [
      { id: 'security', name: 'Security platforms', about: 'Products that protect companies from attacks and help them meet security rules.', metrics: ['arr_growth', 'grr', 'nrr', 'acv', 'sales_cycle', 'pipeline_coverage'], watch: 'Buyers consolidate vendors. Products that become a platform or a must-have for compliance hold up best.' },
      { id: 'identity', name: 'Identity and access', about: 'Products that control who can log in to what, for employees, customers, and machines.', metrics: ['arr_growth', 'nrr', 'grr', 'acv', 'deployment_time'], watch: 'Identity becomes core infrastructure once installed. AI agents need identities too, which opens new ground.' },
      { id: 'cloud-security', name: 'Cloud and application security', about: 'Protecting cloud accounts, code, and applications from attacks and mistakes.', metrics: ['arr_growth', 'nrr', 'acv', 'deployment_time', 'false_positive_rate'], watch: 'Cloud providers add security features of their own. Coverage across several clouds is a common edge.' },
      { id: 'secops', name: 'Security operations', about: 'Tools that detect, investigate, and respond to attacks, increasingly with AI agents.', metrics: ['arr', 'nrr', 'false_positive_rate', 'deployment_time', 'gross_margin'], watch: 'Security teams are short of people. Products that do the work, not just raise alerts, win budget.' },
      { id: 'ai-security', name: 'AI security', about: 'Protecting AI models, agents, and the data they touch.', metrics: ['arr_growth', 'pilot_conversion', 'acv', 'logo_churn'], watch: 'A young category where large security platforms often buy the leaders. Customer budgets may not exist yet.' },
      { id: 'ot-security', name: 'Industrial and critical infrastructure security', about: 'Protecting factories, power grids, water systems, and other physical operations.', metrics: ['acv', 'sales_cycle', 'grr', 'deployment_time', 'contract_value'], watch: 'Long sales cycles and strict rules, but very sticky once deployed. Regulation drives demand.' }
    ] },
  { id: 'fintech', name: 'Fintech', about: 'Financial services and the software that runs them.',
    subsectors: [
      { id: 'payments', name: 'Payments', about: 'Processing, payouts, and money movement for businesses or consumers.', metrics: ['tpv', 'net_take_rate', 'loss_rate', 'nrr', 'gross_margin'], watch: 'Thin margins at scale. Value often comes from software and services built on top of payments.' },
      { id: 'lending', name: 'Lending and credit', about: 'Loans, credit lines, and buy-now-pay-later for consumers or businesses.', metrics: ['originations', 'default_rate', 'nim', 'cost_of_capital', 'cac'], watch: 'Growth is easy; good loans are hard. Judge each loan cohort through a full repayment cycle.' },
      { id: 'banking', name: 'Banking and neobanks', about: 'Accounts, cards, and banking services, often through a partner bank.', metrics: ['deposits', 'primary_account', 'revenue_per_account', 'cost_to_serve', 'cac'], watch: 'Sign-ups are cheap. Funded, primary accounts are what make money.' },
      { id: 'b2b-finance', name: 'Business finance software', about: 'Spend management, accounts payable and receivable, treasury, and accounting automation.', metrics: ['arr', 'tpv', 'net_take_rate', 'nrr', 'logo_churn', 'cac_payback'], watch: 'Many combine software subscriptions with payment revenue. Track both.' },
      { id: 'wealth', name: 'Wealth and investing', about: 'Brokerage, robo-advisors, and tools for investing.', metrics: ['aum', 'revenue_per_account', 'cac', 'cohort_retention', 'deposits'], watch: 'Revenue depends on market levels. Separate net new money from market gains.' },
      { id: 'insurtech', name: 'Insurtech', about: 'New insurers, brokers, and software for insurance companies.', metrics: ['gwp', 'loss_ratio', 'combined_ratio', 'policy_retention', 'attach_rate', 'cac'], watch: 'Loss ratio is the make-or-break number. Fast premium growth with a rising loss ratio is a warning.' },
      { id: 'crypto', name: 'Crypto and digital assets', about: 'Exchanges, wallets, stablecoins, and infrastructure for digital assets.', metrics: ['tpv', 'net_take_rate', 'deposits', 'cohort_retention', 'loss_rate'], watch: 'Volumes swing with asset prices. Regulation can change business models quickly.' }
    ] },
  { id: 'health', name: 'Healthcare', about: 'Care delivery, health software, therapies, and medical devices.',
    subsectors: [
      { id: 'digital-health', name: 'Digital health and virtual care', about: 'Care and coaching delivered online, often paid by employers or health plans.', metrics: ['pmpm', 'engagement_rate', 'clinical_outcomes', 'payer_contracts', 'reimbursement'], watch: 'Payers buy outcomes and savings. Engagement predicts both.' },
      { id: 'health-software', name: 'Healthcare software', about: 'Software for providers, payers, and pharmacies, such as billing, scheduling, and documentation.', metrics: ['arr', 'acv', 'sales_cycle', 'grr', 'nrr', 'gross_margin'], watch: 'Long sales cycles and integration work. Once installed, products tend to stay.' },
      { id: 'biotech', name: 'Biotech and therapeutics', about: 'New drugs and therapies.', metrics: ['clinical_stage', 'milestone_runway', 'regulatory_path'], watch: 'Value moves in steps with clinical data. Most traditional software metrics do not apply.' },
      { id: 'techbio', name: 'AI drug discovery', about: 'Companies using AI and automated labs to find and design new drugs.', metrics: ['pipeline_programs', 'partnership_value', 'milestone_runway', 'clinical_stage'], watch: 'Predictions are cheap; drugs that work in people are not. The test is getting programs into the clinic.' },
      { id: 'medtech', name: 'Medical devices and diagnostics', about: 'Devices, tests, and equipment used in care.', metrics: ['regulatory_path', 'reimbursement', 'asp_unit_margin', 'installed_base', 'milestone_runway'], watch: 'Approval and reimbursement both have to happen before sales scale.' },
      { id: 'lifesci-tools', name: 'Life science tools', about: 'Instruments, software, and supplies used by labs doing research or testing.', metrics: ['installed_base', 'pull_through', 'gross_margin', 'asp_unit_margin', 'sales_cycle'], watch: 'Research budgets swing with funding cycles. Recurring consumables make the business steadier.' },
      { id: 'care-delivery', name: 'Care delivery', about: 'Clinics and services that provide care directly.', metrics: ['provider_utilization', 'reimbursement', 'clinical_outcomes', 'gross_margin', 'cac'], watch: 'Margins depend on clinician utilization and payer rates. Growth needs people, not just software.' }
    ] },
  { id: 'defense', name: 'Defense and national security', about: 'Technology for militaries, intelligence agencies, and homeland security, much of it also sold to commercial customers.',
    subsectors: [
      { id: 'defense', name: 'Defense primes and platforms', about: 'Companies aiming to become full-scale defense contractors that build and integrate entire systems.', metrics: ['program_stage', 'bookings_backlog', 'contract_value', 'sales_cycle'], watch: 'Moving from small pilots to production contracts is slow and decides the outcome.' },
      { id: 'autonomy', name: 'Drones and autonomous systems', about: 'Uncrewed aircraft, boats, and ground vehicles, and the software that lets them operate on their own.', metrics: ['units_fielded', 'program_stage', 'bookings_backlog', 'cost_parity', 'asp_unit_margin'], watch: 'Recent conflicts made cheap, numerous drones a priority. Winning depends on unit cost, production volume, and repeat orders.' },
      { id: 'mission-software', name: 'Defense software and AI', about: 'Software for command and control, intelligence analysis, targeting, logistics, and planning.', metrics: ['program_stage', 'contract_value', 'deployment_time', 'units_fielded', 'dual_use_share'], watch: 'Pilots are easy to win and hard to grow. Look for software that moved into a funded program and runs on real networks.' },
      { id: 'sensing', name: 'Sensing and intelligence', about: 'Radar, sensors, and surveillance systems, plus the data they produce.', metrics: ['program_stage', 'bookings_backlog', 'units_fielded', 'technical_milestones'], watch: 'Performance has to beat established systems in tests run by the customer. Selling the data as well as the hardware helps.' },
      { id: 'ew-comms', name: 'Electronic warfare and communications', about: 'Jamming, protection from jamming, and secure communications and networks.', metrics: ['program_stage', 'contract_value', 'units_fielded', 'deployment_time'], watch: 'Requirements are classified and change fast. Teams with security clearances and close user contact move quicker.' },
      { id: 'defense-manufacturing', name: 'Defense hardware and manufacturing', about: 'Munitions, missiles, hypersonics, shipbuilding, and new factories to produce them faster.', metrics: ['bookings_backlog', 'cost_parity', 'yield', 'program_stage', 'milestone_runway'], watch: 'Capital heavy, with a few large buyers. Multi-year production contracts are what justify building factories.' }
    ] },
  { id: 'space', name: 'Aerospace and space', about: 'Rockets, satellites, aircraft, and the data and services they provide.',
    subsectors: [
      { id: 'launch', name: 'Launch', about: 'Rockets that carry satellites and cargo to orbit.', metrics: ['cost_per_kg', 'flight_heritage', 'bookings_backlog', 'milestone_runway'], watch: 'One dominant provider sets the price. Newcomers need a niche such as small payloads, specific orbits, or defense demand.' },
      { id: 'satellites', name: 'Satellites and spacecraft', about: 'Building satellites and running constellations for communications, sensing, and other services.', metrics: ['flight_heritage', 'bookings_backlog', 'asp_unit_margin', 'cost_parity'], watch: 'Hardware fails and satellites wear out. Customers want proven designs delivered on time.' },
      { id: 'space-data', name: 'Space data and earth observation', about: 'Selling images, radar, and other data collected from orbit, and the analysis built on it.', metrics: ['arr', 'contract_value', 'nrr', 'gross_margin', 'dual_use_share'], watch: 'Government is often the biggest buyer. Commercial demand has grown slower than many expected.' },
      { id: 'in-space', name: 'In-space services and manufacturing', about: 'Refueling, moving, and repairing satellites, space stations, and making products in orbit.', metrics: ['technical_milestones', 'flight_heritage', 'lois_to_orders', 'milestone_runway'], watch: 'Many markets do not exist yet. Government contracts often fund the first missions.' },
      { id: 'aviation', name: 'Aviation and advanced air mobility', about: 'Electric and hybrid aircraft, air taxis, cargo drones, and aviation software.', metrics: ['regulatory_path', 'bookings_backlog', 'lois_to_orders', 'milestone_runway', 'cost_parity'], watch: 'Certification takes years and huge sums. Treat preorders as soft until deposits are paid.' },
      { id: 'space', name: 'Space infrastructure', about: 'Ground stations, space situational awareness, and other systems that support operations in orbit.', metrics: ['bookings_backlog', 'lois_to_orders', 'asp_unit_margin', 'milestone_runway'], watch: 'Large upfront capital and government customers are common.' }
    ] },
  { id: 'climate', name: 'Climate and energy', about: 'Products that cut emissions or change how energy is made, stored, and used.',
    subsectors: [
      { id: 'energy-software', name: 'Energy and grid software', about: 'Software for utilities, grid operators, and energy buyers.', metrics: ['arr', 'acv', 'sales_cycle', 'nrr', 'capacity_deployed'], watch: 'Utility sales cycles are long. Once in, contracts are durable.' },
      { id: 'storage-generation', name: 'Energy storage and generation', about: 'Batteries, solar, wind, geothermal, and other hardware that makes or stores power.', metrics: ['capacity_deployed', 'lcoe', 'capacity_factor', 'offtake', 'asp_unit_margin', 'project_pipeline'], watch: 'Capital heavy. Project financing and offtake contracts often matter more than venture equity.' },
      { id: 'nuclear', name: 'Nuclear fission and fusion', about: 'New reactors, fuel, and fusion power.', metrics: ['technical_milestones', 'permitting_stage', 'offtake', 'cost_parity', 'milestone_runway'], watch: 'Timelines run a decade or more. Licensing, fuel supply, and the first working plant are the key risks.' },
      { id: 'carbon', name: 'Carbon management', about: 'Carbon removal, measurement, and markets.', metrics: ['cost_per_ton', 'verified_tons', 'offtake', 'arr'], watch: 'Demand depends on corporate commitments and policy. Verified delivery is the key proof.' },
      { id: 'electrification', name: 'Electrified transport and buildings', about: 'EVs, charging, heat pumps, and building upgrades.', metrics: ['asp_unit_margin', 'installed_base', 'capacity_factor', 'cac', 'gross_margin'], watch: 'Incentives drive demand and can change. Unit economics should work without them over time.' },
      { id: 'critical-minerals', name: 'Critical minerals and materials', about: 'Mining, refining, and recycling the materials batteries and electronics need, such as lithium, copper, and rare earths.', metrics: ['cost_parity', 'offtake', 'permitting_stage', 'capacity_deployed', 'project_pipeline'], watch: 'Commodity prices swing hard. Long-term offtake contracts and a cost advantage over existing refiners matter most.' },
      { id: 'water', name: 'Water', about: 'Treatment, reuse, and monitoring of water for cities, farms, and industry.', metrics: ['contract_value', 'sales_cycle', 'cost_parity', 'capacity_deployed', 'grr'], watch: 'Water is cheap and buyers are often utilities with slow procurement. Industrial customers with water risk move faster.' }
    ] },
  { id: 'industrial', name: 'Deep tech and industrial', about: 'Hard technology that takes years and significant capital to build, from robots and chips to quantum computers.',
    subsectors: [
      { id: 'robotics', name: 'Robotics and automation', about: 'Robots and automation for factories, warehouses, farms, and other physical work.', metrics: ['asp_unit_margin', 'installed_base', 'capacity_factor', 'bookings_backlog', 'lois_to_orders'], watch: 'Many sell robots as a subscription. Check deployment speed and utilization at each customer.' },
      { id: 'semiconductors', name: 'Semiconductors', about: 'Chips, chip design, and manufacturing equipment.', metrics: ['bookings_backlog', 'yield', 'asp_unit_margin', 'milestone_runway'], watch: 'Very long development cycles. The first production chips and design wins are key milestones.' },
      { id: 'quantum', name: 'Quantum computing and sensing', about: 'Quantum computers, the software to use them, and quantum sensors.', metrics: ['technical_milestones', 'bookings_backlog', 'milestone_runway', 'contract_value'], watch: 'Useful quantum computers are still years away for most problems. Sensing and government research contracts can earn revenue sooner.' },
      { id: 'materials', name: 'Advanced materials', about: 'New materials and chemicals, often discovered with AI, for batteries, chips, construction, and more.', metrics: ['technical_milestones', 'cost_parity', 'yield', 'lois_to_orders', 'milestone_runway'], watch: 'Getting from a lab sample to tons at a competitive cost is the hard part. Customer qualification can take years.' },
      { id: 'manufacturing', name: 'Advanced manufacturing', about: 'New ways to make physical products, such as 3D printing or new materials.', metrics: ['yield', 'asp_unit_margin', 'bookings_backlog', 'capacity_factor'], watch: 'Scaling production is where most of the risk lives.' }
    ] },
  { id: 'consumer', name: 'Consumer', about: 'Products sold directly to people.',
    subsectors: [
      { id: 'consumer-subscription', name: 'Consumer subscriptions', about: 'Paid apps and services billed monthly or yearly.', metrics: ['subscriber_churn', 'cohort_retention', 'paid_conversion', 'cac', 'ltv_cac', 'organic_share'], watch: 'Paid acquisition costs keep rising. Organic growth and retention decide the outcome.' },
      { id: 'social', name: 'Social and communities', about: 'Products where people connect, share, and talk.', metrics: ['dau_mau', 'cohort_retention', 'engagement_time', 'organic_share', 'creator_count'], watch: 'Monetization often comes late. Engagement and retention are the early tests.' },
      { id: 'ecommerce', name: 'E-commerce and consumer brands', about: 'Brands and stores selling physical products online.', metrics: ['aov', 'repeat_rate', 'contribution_margin', 'cac', 'return_rate', 'inventory_turns'], watch: 'Rising ad costs have hurt many brands. Contribution margin after marketing is the real test.' },
      { id: 'consumer-hardware', name: 'Consumer hardware and wearables', about: 'Devices people buy, such as wearables, smart home products, and AI gadgets.', metrics: ['asp_unit_margin', 'return_rate', 'cohort_retention', 'arpu', 'inventory_turns'], watch: 'Hardware needs cash for inventory before sales. Devices that people stop using end up in drawers, so track daily use.' },
      { id: 'gaming', name: 'Gaming', about: 'Games and gaming platforms.', metrics: ['cohort_retention', 'dau_mau', 'arpdau', 'payer_rate', 'cac'], watch: 'Hits are rare and hard to predict. Early retention by cohort is the best leading indicator.' },
      { id: 'media-creator', name: 'Media and creator economy', about: 'Content platforms and tools for creators to earn money.', metrics: ['creator_count', 'arpu', 'engagement_time', 'take_rate', 'cohort_retention'], watch: 'Creators move between platforms. Products that help creators earn more keep them.' },
      { id: 'travel', name: 'Travel and hospitality', about: 'Booking, stays, and software for travelers and hotels.', metrics: ['gmv', 'take_rate', 'buyer_repeat', 'cac', 'contribution_margin'], watch: 'Large booking sites and search engines control demand. Paying for traffic can eat the whole margin.' }
    ] },
  { id: 'marketplaces', name: 'Marketplaces', about: 'Platforms that connect buyers and sellers and take a cut.',
    subsectors: [
      { id: 'goods', name: 'Consumer goods marketplaces', about: 'Buying and selling products, new or used.', metrics: ['gmv', 'take_rate', 'liquidity', 'buyer_repeat', 'aov'], watch: 'Liquidity in each category matters more than total GMV.' },
      { id: 'services', name: 'Services marketplaces', about: 'Booking local services such as home repair, care, or tutoring.', metrics: ['gmv', 'take_rate', 'liquidity', 'time_to_match', 'buyer_repeat', 'supply_utilization'], watch: 'Disintermediation risk: once matched, buyers and providers may go around the platform.' },
      { id: 'b2b-marketplaces', name: 'B2B marketplaces', about: 'Trade between businesses, such as wholesale goods, parts, or freight.', metrics: ['gmv', 'take_rate', 'buyer_repeat', 'liquidity', 'contribution_margin'], watch: 'Large orders and repeat buyers can build revenue quickly, but credit risk and payment terms matter.' },
      { id: 'labor', name: 'Labor and gig marketplaces', about: 'Matching workers with short-term or flexible jobs.', metrics: ['gmv', 'take_rate', 'time_to_match', 'supply_utilization', 'buyer_repeat'], watch: 'Labor rules and worker classification can change economics.' }
    ] },
  { id: 'logistics', name: 'Logistics and mobility', about: 'Moving goods and people.',
    subsectors: [
      { id: 'freight', name: 'Freight and logistics technology', about: 'Brokerage, freight booking, and supply chain software.', metrics: ['shipment_volume', 'margin_per_load', 'on_time', 'nrr', 'take_rate'], watch: 'Freight markets are cyclical. Margins compress when capacity is loose.' },
      { id: 'last-mile', name: 'Last-mile delivery', about: 'Delivering orders to homes and businesses.', metrics: ['cost_per_mile', 'on_time', 'contribution_margin', 'shipment_volume'], watch: 'Density decides economics. Many routes do not pay without enough orders per mile.' },
      { id: 'mobility', name: 'Mobility', about: 'Ride-hailing, fleets, car sharing, and micromobility.', metrics: ['capacity_factor', 'cost_per_mile', 'cohort_retention', 'gross_margin'], watch: 'Capital intensive, with regulation that varies by city.' },
      { id: 'autonomous-vehicles', name: 'Autonomous vehicles', about: 'Self-driving cars, robotaxis, and autonomous trucks.', metrics: ['driverless_miles', 'regulatory_path', 'cost_per_mile', 'capacity_factor', 'milestone_runway'], watch: 'Very capital intensive, with a long tail of rare situations to solve. Expansion city by city shows real progress.' }
    ] },
  { id: 'proptech', name: 'Real estate and construction', about: 'Technology for buying, managing, and building property.',
    subsectors: [
      { id: 'property-software', name: 'Property management software', about: 'Software for landlords and property managers.', metrics: ['units_managed', 'arr', 'logo_churn', 'nrr', 'take_rate'], watch: 'Payments and add-on services often grow revenue per unit.' },
      { id: 'transactions', name: 'Real estate transactions', about: 'Platforms for buying, selling, renting, and financing property.', metrics: ['transaction_volume', 'take_rate', 'cac', 'contribution_margin'], watch: 'Very sensitive to interest rates and housing cycles.' },
      { id: 'construction', name: 'Construction technology', about: 'Software and tools for construction companies.', metrics: ['arr', 'acv', 'sales_cycle', 'grr', 'seat_expansion'], watch: 'A fragmented industry that adopts slowly but stays loyal once onboarded.' }
    ] },
  { id: 'education', name: 'Education', about: 'Learning products for schools, workers, and individuals.',
    subsectors: [
      { id: 'k12', name: 'K-12 education', about: 'Products sold to schools and districts.', metrics: ['contract_value', 'sales_cycle', 'nrr', 'outcome_rate'], watch: 'Budget cycles are annual and seasonal. Funding sources can change.' },
      { id: 'workforce', name: 'Higher education and workforce learning', about: 'Programs that help people gain skills or credentials, often paid by employers.', metrics: ['enrollment', 'completion_rate', 'outcome_rate', 'cac', 'acv'], watch: 'Employers pay for results. Placement and completion are the proof.' },
      { id: 'consumer-learning', name: 'Consumer learning', about: 'Apps and courses people buy for themselves.', metrics: ['cohort_retention', 'subscriber_churn', 'paid_conversion', 'completion_rate', 'cac'], watch: 'Motivation fades. Retention past the first month is the hard part.' }
    ] },
  { id: 'work', name: 'Work and HR', about: 'Products for hiring, paying, and managing employees.',
    subsectors: [
      { id: 'hr-payroll', name: 'HR and payroll', about: 'Payroll, benefits, and HR software.', metrics: ['pepm', 'nrr', 'grr', 'cac_payback', 'arr_growth'], watch: 'Customers rarely switch once payroll runs smoothly. Revenue grows with headcount.' },
      { id: 'recruiting', name: 'Recruiting', about: 'Hiring tools and talent marketplaces.', metrics: ['arr', 'nrr', 'logo_churn', 'take_rate'], watch: 'Spending swings with hiring. Revenue can drop quickly in a slowdown.' },
      { id: 'collaboration', name: 'Collaboration and productivity', about: 'Tools for how teams communicate and get work done.', metrics: ['free_to_paid', 'seat_expansion', 'nrr', 'dau_mau', 'organic_share'], watch: 'Large platforms bundle similar features. Viral, bottom-up adoption is the usual path.' }
    ] },
  { id: 'food-ag', name: 'Food and agriculture', about: 'Farming, food production, and the supply chain behind it.',
    subsectors: [
      { id: 'agtech', name: 'Agriculture technology', about: 'Tools that help farms grow more with less: sensors, software, biologicals, and equipment.', metrics: ['acres_managed', 'customer_roi', 'grr', 'asp_unit_margin'], watch: 'One growing season per year means slow feedback. Renewal after a full season is the real test.' },
      { id: 'food-tech', name: 'Food technology', about: 'New food products and ways of producing food, such as alternative proteins.', metrics: ['asp_unit_margin', 'repeat_rate', 'yield', 'capacity_factor'], watch: 'Reaching cost parity with conventional products at scale is the main hurdle.' }
    ] },
  { id: 'gov', name: 'Government and public sector', about: 'Products for governments and public agencies.',
    subsectors: [
      { id: 'govtech', name: 'Government technology', about: 'Software and services for local, state, and national government.', metrics: ['contract_value', 'sales_cycle', 'grr', 'program_stage'], watch: 'Procurement is slow and rule-bound. Once in, contracts often renew for years.' }
    ] }
];
